package com.shici.app.data.b4
import com.shici.app.core.*
import com.shici.app.data.*
import androidx.test.platform.app.InstrumentationRegistry
import java.util.UUID
import org.junit.Assert.*
import org.junit.Test
import java.time.*
/** Real Android repository on independent UUID database. Compile only; no device authorization. */
class B4StudyRepositoryInstrumentedTest {
 private val now=Instant.parse("2026-10-16T12:00:00Z").toEpochMilli();private val zone=ZoneOffset.UTC
 private fun entry(k:String)=DictionaryEntry(k,"n","meaning $k","synthetic-old","v0")
 private fun plan(vararg keys:String,book:StudyBook=StudyBook.KAOYAN)=StudyMembership(book,keys.toList()){entry(it)}
 private fun <T> repo(f:(LearningRepository)->T):T {val ctx=InstrumentationRegistry.getInstrumentation().targetContext;val name="b4-acceptance-${UUID.randomUUID()}.db";try{return LearningRepository(ctx,name).use(f)}finally{ctx.deleteDatabase(name)}}
 private fun card(r:LearningRepository,k:String="a",at:Long=now)=r.studyView(plan(k),at,zone)
 private fun answer(r:LearningRepository,v:StudyView,k:FeedbackKind=FeedbackKind.KNOW,at:Long=now):StudyCommitOutcome {r.revealStudyCard(v.card!!.token,v.credential);return r.commitStudyFeedback(v.card!!.token,k,at,zone,v.credential)}
 private fun count(r:LearningRepository,t:String)=r.writableDatabase.rawQuery("SELECT COUNT(*) FROM $t",null).use{it.moveToFirst();it.getInt(0)}
 @Test fun emptyMigrationDefaultsNoFakeRows()=repo{r->assertEquals(StudySettings(),r.studySettings());assertEquals(0,count(r,"words"));assertEquals(0,count(r,"study_reviews"));assertEquals(0,count(r,"study_states"))}
 @Test fun dealsImmutablePendingNoLearningOrQuery()=repo{r->val v=card(r);assertNotNull(v.card);assertEquals(0,count(r,"words"));assertEquals(0,count(r,"events"));assertEquals(0,count(r,"study_states"));assertEquals(0L,r.changes.version)}
 @Test fun pendingAndRevealedPhaseSurviveRepeatedRead()=repo{r->val v=card(r);assertEquals(v.card,card(r).card);assertTrue(r.revealStudyCard(v.card!!.token,v.credential));assertTrue(card(r).card!!.answerRevealed);assertEquals(v.card!!.token,card(r).card!!.token)}
 @Test fun rejectFeedbackBeforeReveal()=repo{r->val v=card(r);assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential));assertEquals(0,count(r,"study_reviews"))}
 @Test fun samePayloadRetryIdempotentDifferentPayloadConflict()=repo{r->val v=card(r);assertEquals(StudyCommitOutcome.COMMITTED,answer(r,v));val data=r.backupSnapshot();assertEquals(StudyCommitOutcome.IDEMPOTENT,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential));assertEquals(StudyCommitOutcome.CONFLICT,r.commitStudyFeedback(v.card!!.token,FeedbackKind.FORGET,now,zone,v.credential));assertEquals(data,r.backupSnapshot())}
 @Test fun randomTokenRejected()=repo{r->assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback("unknown",FeedbackKind.KNOW,now,zone));assertEquals(0,count(r,"words"))}
 @Test fun actualFeedbackSeparateFromQueryAndPersonal()=repo{r->val v=card(r);answer(r,v);assertEquals(1,count(r,"words"));assertEquals(1,count(r,"study_reviews"));assertEquals(0,count(r,"events"));assertEquals(emptyList<String>(),r.personalMembers());assertEquals(0,r.snapshot().stats.totalQueries)}
 @Test fun allFeedbackNewWordOnce()=repo{r->val v=card(r);answer(r,v,FeedbackKind.FORGET);val d=card(r,at=now+600000);answer(r,d,FeedbackKind.KNOW,now+600000);val p=card(r,at=now+600000).progress;assertEquals(1,p.introducedToday);assertEquals(1,p.todayReviewed);assertEquals(2,p.todayAnswers)}
 @Test fun quotaExhaustionDoesNotDealAnotherNewCard()=repo{r->r.updateStudySettings(StudyBook.KAOYAN,1);answer(r,r.studyView(plan("a","b"),now,zone));val v=r.studyView(plan("a","b"),now,zone);assertEquals(0,v.progress.newRemaining);assertNull("quota exhausted must not deal new card",v.card)}
 @Test fun crossBookQuotaCannotBeBypassed()=repo{r->r.updateStudySettings(StudyBook.KAOYAN,1);answer(r,card(r));r.updateStudySettings(StudyBook.CET6,1);val v=r.studyView(plan("b",book=StudyBook.CET6),now,zone);assertEquals(1,v.progress.introducedToday);assertNull(v.card)}
 @Test fun raisingGoalContinuesWithoutReset()=repo{r->r.updateStudySettings(StudyBook.KAOYAN,1);answer(r,card(r));r.updateStudySettings(StudyBook.KAOYAN,2);val v=r.studyView(plan("a","b"),now,zone);assertEquals(1,v.progress.introducedToday);assertEquals("b",v.card!!.entryKey)}
 @Test fun loweringGoalInvalidatesOverQuotaPending()=repo{r->r.updateStudySettings(StudyBook.KAOYAN,2);answer(r,card(r));val v=card(r,"b");r.revealStudyCard(v.card!!.token,v.credential);r.updateStudySettings(StudyBook.KAOYAN,1);assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential))}
 @Test fun midnightOldPendingCannotCommit()=repo{r->val v=card(r);r.revealStudyCard(v.card!!.token,v.credential);assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now+StudyRules.DAY_MILLIS,zone,v.credential))}
 @Test fun timezoneCrossDateRequiresRefresh()=repo{r->val t=Instant.parse("2026-10-16T20:00:00Z").toEpochMilli();val v=card(r,at=t);r.revealStudyCard(v.card!!.token,v.credential);assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,t,ZoneId.of("Asia/Shanghai"),v.credential))}
 @Test fun switchBookOldCardCannotCommit()=repo{r->val v=card(r);r.revealStudyCard(v.card!!.token,v.credential);r.updateStudySettings(StudyBook.CET6,20);assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential))}
 @Test fun newViewAfterSwitchDiscardsOldToken()=repo{r->val v=card(r);r.updateStudySettings(StudyBook.CET6,20);val next=r.studyView(plan("b",book=StudyBook.CET6),now,zone);assertNotEquals(v.card!!.token,next.card!!.token);assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential))}
 @Test fun crossBookSharesStateNotNewCount()=repo{r->answer(r,card(r),FeedbackKind.FORGET);r.updateStudySettings(StudyBook.CET6,20);val v=r.studyView(plan("a",book=StudyBook.CET6),now+600000,zone);assertFalse(v.card!!.newWord);answer(r,v,at=now+600000);assertEquals(1,count(r,"study_states"));assertEquals(1,v.progress.introducedToday)}
 @Test fun dueStableOrderAndPriority()=repo{r->answer(r,card(r,"b"),FeedbackKind.FORGET);answer(r,card(r,"a"),FeedbackKind.FORGET);val v=r.studyView(plan("new","b","a"),now+600000,zone);assertEquals("a",v.card!!.entryKey);assertFalse(v.card!!.newWord)}
 @Test fun futureRelearnDoesNotBlockAvailableNew()=repo{r->answer(r,card(r),FeedbackKind.FORGET);val v=r.studyView(plan("a","b"),now,zone);assertEquals("b",v.card!!.entryKey);assertEquals(now+600000,v.progress.nextDueAt)}
 @Test fun exactDueBoundary()=repo{r->answer(r,card(r),FeedbackKind.FORGET);assertNull(card(r,at=now+599999).card);assertNotNull(card(r,at=now+600000).card)}
 @Test fun deleteRemovesAllLearningForOnlyKey()=repo{r->answer(r,card(r));answer(r,card(r,"b"));val old=r.deletions.capture();assertEquals(DeleteOutcome.DELETED,r.deleteWord("a",old));val d=r.backupSnapshot().data;assertEquals(listOf("b"),d.words.map{it.entryKey});assertEquals(listOf("b"),d.states.map{it.entryKey});assertEquals(listOf("b"),d.reviews.map{it.entryKey});assertTrue(r.deletions.isStale("a",old));assertFalse(r.deletions.isStale("b",old))}
 @Test fun deletePendingBrandNewInvalidatesToken()=repo{r->val v=card(r);r.deleteWord("a",v.credential);assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential));assertEquals(0,count(r,"study_session"))}
 @Test fun deletionRealEngineRollbackPreservesRows()=repo{r->answer(r,card(r));val before=r.backupSnapshot();r.writableDatabase.execSQL("CREATE TRIGGER stopdelete BEFORE DELETE ON words BEGIN SELECT RAISE(ABORT, 'injected'); END");try{r.deleteWord("a",r.deletions.capture());fail("expected trigger failure")}catch(e:android.database.SQLException){};assertEquals(before,r.backupSnapshot())}
 @Test fun feedbackTriggerFailureRollsBackAndRetrySameCard()=repo{r->val v=card(r);r.revealStudyCard(v.card!!.token,v.credential);val before=r.backupSnapshot();r.writableDatabase.execSQL("CREATE TRIGGER stopreview BEFORE INSERT ON study_reviews BEGIN SELECT RAISE(ABORT, 'injected'); END");try{r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential);fail("expected trigger failure")}catch(e:android.database.SQLException){};assertEquals(before,r.backupSnapshot());r.writableDatabase.execSQL("DROP TRIGGER stopreview");assertEquals(StudyCommitOutcome.COMMITTED,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential))}
 @Test fun canCommitFalsePreservesCardAndRows()=repo{r->val v=card(r);r.revealStudyCard(v.card!!.token,v.credential);val before=r.backupSnapshot();assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential){false});assertEquals(before,r.backupSnapshot())}
 @Test fun restoreAllTablesAndGlobalOldCardBarrier()=repo{r->val v=card(r);r.revealStudyCard(v.card!!.token,v.credential);val d=r.backupSnapshot();assertEquals(RestoreOutcome.RESTORED,r.restoreBackup(d.data,d.revision));assertEquals(d.data,r.backupSnapshot().data);assertEquals(StudyCommitOutcome.STALE,r.commitStudyFeedback(v.card!!.token,FeedbackKind.KNOW,now,zone,v.credential));val fresh=card(r);assertEquals(v.card!!.token,fresh.card!!.token);assertEquals(StudyCommitOutcome.COMMITTED,answer(r,fresh))}
 @Test fun restoreRevisionDriftRefusesAllTables()=repo{r->val d=r.backupSnapshot();r.updateStudySettings(StudyBook.CET6,50);val before=r.backupSnapshot();assertEquals(RestoreOutcome.REVISION_CHANGED,r.restoreBackup(d.data,d.revision));assertEquals(before,r.backupSnapshot())}
 @Test fun restoreTriggerFailureRollsBackAllTables()=repo{r->answer(r,card(r));val before=r.backupSnapshot();r.writableDatabase.execSQL("CREATE TRIGGER stoprestore BEFORE DELETE ON words BEGIN SELECT RAISE(ABORT, 'injected'); END");try{r.restoreBackup(LearningBackupData(emptyList(),emptyList()),before.revision);fail("expected trigger")}catch(e:android.database.SQLException){};assertEquals(before,r.backupSnapshot())}
 @Test fun v1PayloadRestoreClearsStudyNotLegacyNotes()=repo{r->answer(r,card(r));val old=BackupWord("legacy","legacy","n","old meaning","old","v0",true,"note");val rev=r.changes.version;r.restoreBackup(LearningBackupData(listOf(old),listOf(BackupEvent("revoked","legacy","x","x",1,true))),rev);val d=r.backupSnapshot().data;assertEquals(old,d.words.single());assertEquals(0,d.states.size);assertEquals(0,d.reviews.size);assertEquals(StudySettings(),r.studySettings());assertNull(d.session)}
 @Test fun activeQueriesOnlyPersonalMembership()=repo{r->for(k in listOf("a","b")){r.record(QueryEvent(k,k,k,k,now),entry(k))};r.revoke("b");answer(r,card(r,"bookonly"));assertEquals(listOf("a"),r.personalMembers())}
 @Test fun originalMasteryNotesSourcesPreservedByStudy()=repo{r->r.record(QueryEvent("q","a","a","a",now),entry("a"));r.updateWord("a",true,"my note");answer(r,card(r));val w=r.backupSnapshot().data.words.single();assertTrue(w.mastered);assertEquals("my note",w.note);assertEquals("synthetic-old",w.source);assertEquals(1,count(r,"events"))}
 @Test fun originalRevokedRawEventSurvivesV2RoundTrip()=repo{r->r.record(QueryEvent("q","a","x","a",now),entry("a"));r.revoke("q");val d=r.backupSnapshot().data;assertTrue(d.events.single().revoked);val decoded=LearningBackupCodec.decode(LearningBackupCodec.encode(d,"1.0.0",12,now));assertEquals(d,decoded.data)}
 @Test fun oldDateLedgerReused()=repo{r->answer(r,card(r));val tomorrow=card(r,"b",now+StudyRules.DAY_MILLIS);answer(r,tomorrow,at=now+StudyRules.DAY_MILLIS);assertEquals(1,card(r,"c",now).progress.introducedToday);assertEquals(2,count(r,"study_reviews"))}
 @Test fun settingsClampedAndPersisted()=repo{r->r.updateStudySettings(StudyBook.PERSONAL,999);assertEquals(StudySettings(StudyBook.PERSONAL,200),r.studySettings());r.updateStudySettings(StudyBook.KAOYAN,-5);assertEquals(1,r.studySettings().dailyNewGoal)}
 @Test fun removedPersonalMemberCannotRemainPending()=repo{r->r.record(QueryEvent("q","a","a","a",now),entry("a"));r.updateStudySettings(StudyBook.PERSONAL,20);val v=r.studyView(StudyMembership(StudyBook.PERSONAL,r.personalMembers()){null},now,zone);assertNotNull(v.card);r.revoke("q");val next=r.studyView(StudyMembership(StudyBook.PERSONAL,r.personalMembers()){null},now,zone);assertNull("no longer active personal member",next.card)}
 @Test fun progressObserverFiresOnlyAfterRealCommit()=repo{r->val v=card(r);r.revealStudyCard(v.card!!.token,v.credential);var calls=0;var inTransaction=true;var rows=-1;val listener:(Long)->Unit={calls++;inTransaction=r.writableDatabase.inTransaction();rows=count(r,"study_reviews")};r.changes.observe(listener);answer(r,v);assertEquals(1,calls);assertFalse(inTransaction);assertEquals(1,rows)}
 @Test fun malformedV2FeedbackActuallyInflatesLedgerIfRestored()=repo{r->answer(r,card(r));val d=r.backupSnapshot();val duplicate=d.data.reviews.single().copy(token="duplicate-introduction",reviewedAt=now+1);val bytes=LearningBackupCodec.encode(d.data.copy(reviews=d.data.reviews+duplicate),"1.0.0",12,now);try{val decoded=LearningBackupCodec.decode(bytes);r.restoreBackup(decoded.data,d.revision);assertEquals("one introduced word cannot consume 2 daily slots",1,card(r,"b").progress.introducedToday)}catch(e:BackupFormatException){/* reject before restore is safe */}}
}
